modules={}
for name,module in list(sys.modules.items()):
 p=getattr(module,'__file__',None)
 if p and str(ROOT)+'/'in str(p):modules[name]={'path':str(Path(p).relative_to(ROOT)),'sha256':sha(p)}
commands=[]
for script,log in [('analyze_v24_convex_covers.py','full-run.log'),('extend_v24_obstructions.py','obstructions-run.log'),('verify_v24_certificates.py','verification.log')]:
 p=ROOT/'debug/issue25/v24-cover'/log
 commands.append({'command':'OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 /data_robot/projects/.worktrees/nero-gripper-grasp-diagnosis/.venv/bin/python -B scripts/'+script,'exit_code':0,'log_path':str(p.relative_to(ROOT)),'log_sha256':sha(p),'full_stdout_stderr':p.read_text()})
comment=json.loads((ROOT/'debug/issue25/v24-cover/task-comment.json').read_text())
provenance={'status':'V24_CONVEX_COVER_MIXED','task_comment':{'url':comment['html_url'],'id':comment['id'],'updated_at':comment['updated_at'],'body_sha256':hashlib.sha256(comment['body'].encode()).hexdigest()},'worktree':str(ROOT),'branch':cmd(['git','branch','--show-current']),'predecessor_commit':cmd(['git','rev-parse','HEAD']),'base346_commit':'6eba4f34c5ff5029eb849804e3d2e9c535f58756','base_geometry_sha256':'79bef01f443035c6db2213c0e73531c079cdb97762361e682d7c9d052edac84e','v23_geometry_sha256':'4050c488325b409532360ee9d8dc3311bd3a53bc36b75949af637bfc8b59fd96','no_new_runtime_geometry':True,'cap_normalization':'NONE','frozen_inputs_sha256':v['frozen_input_sha256'],'all_delivered_files_sha256':{str(p.relative_to(ROOT)):sha(p)for p in files},'imported_project_and_private_vendor_modules_on_same_analysis_import_path':modules,'environment':{'python':sys.version,'python_executable':sys.executable,'numpy':numpy.__version__,'scipy':scipy.__version__,'platform':platform.platform(),'os_release':Path('/etc/os-release').read_text()},'successful_commands':commands,'independent_verification':v,'initial_verifier_rounding_issue':'Independent replay detected objective-offset binary64 subtraction vs rational subtraction mismatch. Analysis-only certificate bookkeeping corrected to bound the actual stored offset; all final certificates regenerated/replayed. Frozen inputs unchanged.','no_MuJoCo_import':True,'unchanged_preexisting_tracked_files':subprocess.run(['git','diff','--exit-code'],cwd=ROOT,capture_output=True).returncode==0,'scope':'No runtime candidate, vertices/faces edit, policy edit, cap normalization, physics/query/integration, benchmark, new Issue or main edit.'}
provenance['audit_source']=Path(__file__).read_text()
(ROOT/'reports/nero-gripper-v24-provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
print(json.dumps({'status':provenance['status'],'delivered_files':len(files),'project_and_private_vendor_modules':len(modules),'no_MuJoCo_import':True},indent=2))
